cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
shapes=[]
# square
for r in range(6):
 for c in range(6):
  s={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if s<=cells: shapes.append(('sq',s))
# L triominoes: all 3 of 2x2
for r in range(6):
 for c in range(6):
  block={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for missing in block:
   s=block-{missing}
   if s<=cells: shapes.append(('L',s))
sol=[]
def rec(rem, picked):
 if not rem:
  if sum(k=='sq' for k,s in picked)==1 and len(picked)==5: sol.append(picked)
  return
 if len(picked)>=5:return
 x=min(rem)
 for k,s in shapes:
  if x in s and s<=rem:
   rec(rem-s,picked+[(k,s)])
rec(cells,[])
print('solutions',len(sol))
for p in sol[:10]:
 print([(k,sorted(s)) for k,s in p])
